import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Change Actor State","description":"","frontmatter":{"title":"Change Actor State","order":4},"headers":[],"relativePath":"en/latest/tutorial/script/actor/actor-change-state.md","filePath":"en/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1788455378000}'),s={name:"en/latest/tutorial/script/actor/actor-change-state.md"};function n(i,t,d,c,h,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="change-actor-state" tabindex="-1">Change Actor State <a class="header-anchor" href="#change-actor-state" aria-label="Permalink to &quot;Change Actor State&quot;">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Switch the state of the specified actor. Characters that can safely provide state frames use a true visual blend; other characters automatically fall back to fading out, applying the state, and fading in. Story execution resumes after the transition finishes.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;character name&gt; &lt;new state&gt;</span></span></code></pre></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Character</td><td>Yes</td><td>kona</td><td>Name of the actor whose state should be changed</td></tr><tr><td>New state</td><td>Yes</td><td>happy</td><td>New state to switch to</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="state-transition" tabindex="-1">State transition <a class="header-anchor" href="#state-transition" aria-label="Permalink to &quot;State transition&quot;">​</a></h2><p><code>actor change</code> selects the transition path automatically:</p><ol><li>If the character scene provides current and target state frames, blend them with a premultiplied-alpha shader.</li><li>Otherwise, safely fade the current actor out, apply the state, and fade it in.</li><li>Continue with the next story command after the transition finishes.</li></ol><p>Configure the transition in the Inspector for the <code>KonadoStageController</code> node:</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>actor_state_transition_enabled</code></td><td><code>true</code></td><td>Enables the fade transition for actor state changes</td></tr><tr><td><code>actor_state_transition_duration</code></td><td><code>0.3</code></td><td>Total transition duration in seconds; the safe fallback splits it equally between fade-out and fade-in</td></tr></tbody></table><p>Disable <code>actor_state_transition_enabled</code> or set <code>actor_state_transition_duration</code> to <code>0</code> to switch states immediately.</p><p>Transitions never duplicate the character scene. The bundled AnimatedSprite2D example uses pure texture frames for a true blend. A custom state frame must represent the complete character image, not just one visible component. Video, Spine, Live2D, and custom scenes without complete, safe state frames automatically use the fallback, so scripts, audio, and dynamic media are never started twice. If the target actor is missing or its scene cannot apply the state, Konado completes the command and continues the story instead of waiting indefinitely.</p>',16)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
